#include <openssl/evp.h>
#include <openssl/rand.h>
#include <cstring>
#include <string>
#include <vector>
#include <chrono>
#include <thread>
#include <unordered_map>
#include <mutex>
#include <stdexcept>

namespace cicd {
namespace crypto {

struct TenantContext {
    std::string tenant_id;
    std::vector<unsigned char> encryption_key;
    std::vector<unsigned char> hmac_key;
    uint64_t key_version;
};

class ArtifactEncryptor {
private:
    std::unordered_map<std::string, TenantContext> tenants_;
    std::mutex mu_;

    static constexpr int AES_BLOCK_SIZE = 16;
    static constexpr int KEY_SIZE = 32;
    static constexpr int IV_SIZE = 16;
    static constexpr int HMAC_SIZE = 32;

    enum class DecryptStatus {
        SUCCESS = 0,
        HMAC_FAILURE = 1,
        PADDING_FAILURE = 2,
        INTERNAL_ERROR = 3
    };

    bool verify_hmac(const TenantContext& ctx, const unsigned char* data, 
                     size_t data_len, const unsigned char* expected_hmac) {
        unsigned char computed[HMAC_SIZE];
        unsigned int computed_len = 0;

        EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
        EVP_PKEY* pkey = EVP_PKEY_new_mac_key(EVP_PKEY_HMAC, nullptr,
            ctx.hmac_key.data(), ctx.hmac_key.size());

        EVP_DigestSignInit(mdctx, nullptr, EVP_sha256(), nullptr, pkey);
        EVP_DigestSignUpdate(mdctx, data, data_len);
        size_t sig_len = HMAC_SIZE;
        EVP_DigestSignFinal(mdctx, computed, &sig_len);

        EVP_PKEY_free(pkey);
        EVP_MD_CTX_free(mdctx);

        return CRYPTO_memcmp(computed, expected_hmac, HMAC_SIZE) == 0;
    }

    DecryptStatus decrypt_artifact_internal(const TenantContext& ctx,
                                            const std::vector<unsigned char>& ciphertext,
                                            std::vector<unsigned char>& plaintext) {
        if (ciphertext.size() < IV_SIZE + AES_BLOCK_SIZE + HMAC_SIZE) {
            return DecryptStatus::INTERNAL_ERROR;
        }

        size_t enc_len = ciphertext.size() - HMAC_SIZE;
        const unsigned char* hmac_ptr = ciphertext.data() + enc_len;

        if (!verify_hmac(ctx, ciphertext.data(), enc_len, hmac_ptr)) {
            return DecryptStatus::HMAC_FAILURE;
        }

        const unsigned char* iv = ciphertext.data();
        const unsigned char* enc_data = ciphertext.data() + IV_SIZE;
        int enc_data_len = enc_len - IV_SIZE;

        EVP_CIPHER_CTX* cipher_ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), nullptr,
                          ctx.encryption_key.data(), iv);

        plaintext.resize(enc_data_len + AES_BLOCK_SIZE);
        int out_len = 0;
        int total_len = 0;

        EVP_DecryptUpdate(cipher_ctx, plaintext.data(), &out_len,
                         enc_data, enc_data_len);
        total_len = out_len;

        int final_result = EVP_DecryptFinal_ex(cipher_ctx, 
                                               plaintext.data() + total_len, &out_len);
        EVP_CIPHER_CTX_free(cipher_ctx);

        if (final_result != 1) {
            return DecryptStatus::PADDING_FAILURE;
        }

        total_len += out_len;
        plaintext.resize(total_len);
        return DecryptStatus::SUCCESS;
    }

public:
    void register_tenant(const std::string& tenant_id,
                        const std::vector<unsigned char>& enc_key,
                        const std::vector<unsigned char>& hmac_key) {
        std::lock_guard<std::mutex> lock(mu_);
        tenants_[tenant_id] = {tenant_id, enc_key, hmac_key, 1};
    }

    struct DecryptResult {
        bool success;
        int error_code;
        std::vector<unsigned char> data;
        std::string error_message;
    };

    DecryptResult decrypt_pipeline_artifact(const std::string& tenant_id,
                                           const std::vector<unsigned char>& artifact) {
        std::lock_guard<std::mutex> lock(mu_);

        auto it = tenants_.find(tenant_id);
        if (it == tenants_.end()) {
            return {false, 4, {}, "Unknown tenant"};
        }

        std::vector<unsigned char> plaintext;
        auto status = decrypt_artifact_internal(it->second, artifact, plaintext);

        switch (status) {
            case DecryptStatus::SUCCESS:
                return {true, 0, std::move(plaintext), ""};
            case DecryptStatus::HMAC_FAILURE:
                return {false, static_cast<int>(status), {}, "Integrity check failed"};
            case DecryptStatus::PADDING_FAILURE:
                return {false, static_cast<int>(status), {}, "Decryption failed: padding error"};
            case DecryptStatus::INTERNAL_ERROR:
                return {false, static_cast<int>(status), {}, "Internal processing error"};
        }
        return {false, -1, {}, "Unknown error"};
    }

    std::vector<unsigned char> encrypt_pipeline_artifact(
            const std::string& tenant_id,
            const std::vector<unsigned char>& plaintext) {
        std::lock_guard<std::mutex> lock(mu_);

        auto it = tenants_.find(tenant_id);
        if (it == tenants_.end()) {
            throw std::runtime_error("Unknown tenant");
        }

        const auto& ctx = it->second;
        std::vector<unsigned char> iv(IV_SIZE);
        RAND_bytes(iv.data(), IV_SIZE);

        EVP_CIPHER_CTX* cipher_ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), nullptr,
                          ctx.encryption_key.data(), iv.data());

        std::vector<unsigned char> output(IV_SIZE + plaintext.size() + 2 * AES_BLOCK_SIZE);
        std::memcpy(output.data(), iv.data(), IV_SIZE);

        int out_len = 0;
        int total_len = 0;
        EVP_EncryptUpdate(cipher_ctx, output.data() + IV_SIZE, &out_len,
                         plaintext.data(), plaintext.size());
        total_len = out_len;

        EVP_EncryptFinal_ex(cipher_ctx, output.data() + IV_SIZE + total_len, &out_len);
        total_len += out_len;
        EVP_CIPHER_CTX_free(cipher_ctx);

        output.resize(IV_SIZE + total_len);

        // Compute HMAC over IV + ciphertext
        unsigned char hmac[HMAC_SIZE];
        EVP_MD_CTX* mdctx = EVP_MD_CTX_new();
        EVP_PKEY* pkey = EVP_PKEY_new_mac_key(EVP_PKEY_HMAC, nullptr,
            ctx.hmac_key.data(), ctx.hmac_key.size());
        EVP_DigestSignInit(mdctx, nullptr, EVP_sha256(), nullptr, pkey);
        EVP_DigestSignUpdate(mdctx, output.data(), output.size());
        size_t sig_len = HMAC_SIZE;
        EVP_DigestSignFinal(mdctx, hmac, &sig_len);
        EVP_PKEY_free(pkey);
        EVP_MD_CTX_free(mdctx);

        output.insert(output.end(), hmac, hmac + HMAC_SIZE);
        return output;
    }
};

} // namespace crypto
} // namespace cicd
